using Servicio.RetazoMarket.Business.DTOs.Favorito;using Servicio.RetazoMarket.DataManagment.Models;
namespace Servicio.RetazoMarket.Business.Mappers;public static class FavoritoBusinessMapper {public static FavoritoDataModel ToDataModel(AgregarFavoritoRequest r)=>new(){id_cliente=r.id_cliente,id_producto=r.id_producto};public static FavoritoResponse ToResponse(FavoritoDataModel m){var p=m.Producto;return new(){id_cliente=m.id_cliente,id_producto=m.id_producto,producto_nombre=p?.prod_nombre,producto_descripcion=p?.prod_descripcion,colores=p is null?default:p.colores.Clone(),precio_base=p?.precio_base,stock_actual=p?.stock_actual,prod_estado=p?.prod_estado,linea_nombre=p?.Linea?.lin_nombre,imagen_principal_url=p?.Imagenes.FirstOrDefault(x=>x.es_principal=="S")?.url};}}
